export const getTranslation = (path, lang = state.language) => {
    const dict = i18nDictionaries[lang] || i18nDictionaries.es;
    const keys = path.split('.');
    let current = dict;
    for (const key of keys) {
        if (current && typeof current === 'object' && key in current) {
            current = current[key];
        } else {
            let fallback = i18nDictionaries.es;
            for (const fKey of keys) {
                if (fallback && typeof fallback === 'object' && fKey in fallback) {
                    fallback = fallback[fKey];
                } else {
                    return null;
                }
            }
            return fallback;
        }
    }
    return current;
};

export const updateDocumentLocalization = () => {
    const lang = state.language;
    if (typeof document !== 'undefined') document.documentElement.lang = lang;

    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        const trans = getTranslation(key, lang);
        if (trans && typeof trans === 'string') {
            el.textContent = trans;
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        const trans = getTranslation(key, lang);
        if (trans && typeof trans === 'string') {
            el.placeholder = trans;
        }
    });

    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        const trans = getTranslation(key, lang);
        if (trans && typeof trans === 'string') {
            el.title = trans;
        }
    });

    document.querySelectorAll('[data-i18n-prompt]').forEach(el => {
        const key = el.getAttribute('data-i18n-prompt');
        const trans = getTranslation(key, lang);
        if (trans && typeof trans === 'string') {
            el.setAttribute('data-prompt', trans);
        }
    });

    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
        const key = el.getAttribute('data-i18n-aria');
        const trans = getTranslation(key, lang);
        if (trans && typeof trans === 'string') {
            el.setAttribute('aria-label', trans);
        }
    });

    if (typeof window !== 'undefined' && window.spacesManager?.renderHeaderSwitcher) {
        window.spacesManager.renderHeaderSwitcher();
    }
};

export async function loadLocaleAsync(lang) {
    try {
        const res = await fetch(`./locales/${lang}.json`);
        if (res.ok) {
            const data = await res.json();
            i18nDictionaries[lang] = deepMerge(i18nDictionaries[lang] || {}, data);
            return i18nDictionaries[lang];
        }
    } catch (e) {}
    return i18nDictionaries[lang] || i18nDictionaries.es;
}

function deepMerge(base, overlay) {
    if (!overlay || typeof overlay !== 'object' || Array.isArray(overlay)) return overlay;
    const out = { ...(base || {}) };
    Object.keys(overlay).forEach((k) => {
        if (overlay[k] && typeof overlay[k] === 'object' && !Array.isArray(overlay[k])) {
            out[k] = deepMerge(out[k] || {}, overlay[k]);
        } else {
            out[k] = overlay[k];
        }
    });
    return out;
}
